def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        safe_bid = min(budget, DAILY_SALARY * 0.35)
        if hp <= 2 or no_water_days >= 2:
            safe_bid = min(budget, DAILY_SALARY * 0.8)
        return max(0.0, float(safe_bid))

    pressure_bids = []
    desperate_bids = []
    rich_aggressive = 0
    weak_opponents = 0
    total_req = WATER_REQ

    for opp in alive:
        total_req += opp.get('water_requirement', WATER_REQ)
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 2:
            desperate_bids.append(opp)
        if opp.get('hp', 10) <= 2:
            weak_opponents += 1
        if opp.get('budget', 0) >= 200:
            rich_aggressive += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            pressure_bids.append(float(prev.get('bid', 0.0)))

    max_prev = max(pressure_bids) if pressure_bids else 0.0
    avg_prev = sum(pressure_bids) / len(pressure_bids) if pressure_bids else 0.0

    scarcity = total_req / max(1.0, supply)
    very_tight = supply <= 16
    ample = supply >= 22

    emergency = hp <= 2 or no_water_days >= 2
    fragile = hp <= 4 or no_water_days >= 1

    if emergency:
        bid = max(DAILY_SALARY * 0.95, max_prev + 2.0)
        if desperate_bids:
            bid = max(bid, avg_prev + 3.0)
        return max(0.0, float(min(budget, bid)))

    if very_tight:
        if max_prev >= 120:
            bid = DAILY_SALARY * 0.42 if hp >= 6 else DAILY_SALARY * 0.88
        elif max_prev >= 80:
            bid = max(DAILY_SALARY * 0.62, max_prev + 1.5)
        else:
            bid = DAILY_SALARY * 0.58 + weak_opponents * 2.0
    elif ample:
        if max_prev >= 110 and hp >= 6:
            bid = DAILY_SALARY * 0.28
        else:
            bid = DAILY_SALARY * 0.4
    else:
        if max_prev >= 120:
            bid = DAILY_SALARY * 0.35 if hp >= 7 else DAILY_SALARY * 0.82
        elif max_prev >= 90:
            bid = DAILY_SALARY * 0.48 if hp >= 6 else DAILY_SALARY * 0.72
        elif max_prev > 0:
            bid = max(DAILY_SALARY * 0.5, min(max_prev + 1.2, DAILY_SALARY * 0.78))
        else:
            bid = DAILY_SALARY * 0.52

    if scarcity > 2.2:
        bid += 8.0
    elif scarcity < 1.7:
        bid -= 5.0

    if desperate_bids and hp >= 5:
        target = 0.0
        for opp in desperate_bids:
            prev = opp.get('previous_trace', {})
            obid = float(prev.get('bid', 0.0)) if prev and prev.get('bid') is not None else DAILY_SALARY * 0.55
            if obid > target:
                target = obid
        bid = max(bid, target + 1.1)

    if rich_aggressive >= 2 and max_prev >= 100 and hp >= 7 and not very_tight:
        bid = min(bid, DAILY_SALARY * 0.33)

    if fragile:
        bid = max(bid, DAILY_SALARY * 0.68)

    if day >= 8:
        bid += 4.0
    if day >= 9 and hp <= 5:
        bid += 8.0

    if budget < DAILY_SALARY * 2:
        bid = min(bid, budget * 0.72)
    elif budget > 400 and hp <= 5:
        bid += 6.0

    bid = max(0.0, min(float(bid), float(budget)))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None and prev.get('day') == day_context['day'] - 1:
            yesterday_bids.append(prev['bid'])

    bid_value = DAILY_SALARY * 0.75

    if my_status['hp'] <= 2:
        bid_value = DAILY_SALARY * 0.98
    elif my_status['hp'] <= 4:
        bid_value = max(bid_value, DAILY_SALARY * 0.9)
    elif my_status['hp'] <= 6:
        bid_value = max(bid_value, DAILY_SALARY * 0.8)

    if day_context['day'] >= int(EPISODE_DAYS * 0.7):
        if my_status['hp'] <= 5:
            bid_value = max(bid_value, DAILY_SALARY * 0.95)
        else:
            bid_value = max(bid_value, DAILY_SALARY * 0.8)

    supply = day_context['supply']
    if supply < WATER_REQ:
        if my_status['hp'] <= 3:
            bid_value = max(bid_value, DAILY_SALARY * 0.99)
        else:
            bid_value = min(bid_value, DAILY_SALARY * 0.5)
    elif supply < WATER_REQ * 2:
        if my_status['hp'] <= 4:
            bid_value = max(bid_value, DAILY_SALARY * 0.92)
        else:
            bid_value = max(bid_value, DAILY_SALARY * 0.78)
    elif my_status['hp'] > 7:
        bid_value = min(bid_value, DAILY_SALARY * 0.65)

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if my_status['hp'] <= 3:
                bid_value = max(bid_value, highest_prev_bid + 5)
            else:
                bid_value = max(bid_value, highest_prev_bid + 1)
        elif highest_prev_bid >= DAILY_SALARY * 0.5:
            bid_value = max(bid_value, highest_prev_bid + 2)
        else:
            bid_value = max(bid_value, DAILY_SALARY * 0.65)

    final_bid = min(my_status['budget'], bid_value)
    final_bid = max(final_bid, DAILY_SALARY * 0.25)

    return final_bid

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 140
    WATER_REQ = 8
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
